package validation;

import domain.User;


/**
 * Validates user IDs and names without modifying the user. Instances have no
 * configuration and can be created with the implicit public constructor.
 * Names must be non-null and nonblank; storage format restrictions belong to
 * the FILE repository, not this common validator.
 */
public class UserValidator implements Validator<User>{
    /**
     * Validates user names and optional identifiers.
     * A null ID is allowed for users whose ID will be generated by storage.
     * A non-null ID must be positive.
     *
     * @param entity the user to validate
     * @throws ValidationException if the user is null,
     *         its ID is nonpositive, or its names are invalid
     */
    @Override
    public void validate(User entity) {
        if(entity == null)
        {
            throw new ValidationException("User cannot be null!");
        }
        if(entity.getId() != null && entity.getId() <= 0L)
        {
            throw new ValidationException("ID must be positive!");
        }

        if (entity.getFirstName() == null || entity.getFirstName().isBlank()) {
            throw new ValidationException("First name cannot be empty!");
        }

        if (entity.getLastName() == null || entity.getLastName().isBlank()) {
            throw new ValidationException("Last name cannot be empty!");
        }
    }
}
